actions.script:
                def typeEnum = ec.entity.find("moqui.basic.Enumeration")
                    .condition("enumId", policy.policyTypeEnumId).useCache(true).one()
                String coverageText = (shown.coverages ?: []).collect {
                    "- ${it.coverageName}: limit ${it.limitAmount ?: 'not stated'}, deductible ${it.deductibleAmount ?: 'none'}"
                }.join("\n")
                String prompt = """Explain this insurance policy to the policyholder in plain, friendly
${new Locale(language).getDisplayLanguage(Locale.ENGLISH)}, as a short list of at most 6 lines,
each starting with "• ". No markdown, no headings. Use ONLY the facts below. Do not invent
exclusions, prices, discounts or legal rules: where the policy data does not say, tell the reader
to ask the agency. Explain what the limit and deductible mean with the actual numbers.
Include one line on what to do first after an accident or loss: keep safe, take photos, report
the claim in the app.

Policy type: ${typeEnum?.description ?: policy.policyTypeEnumId}
Insurer: ${shown.carrierName}
Valid: ${ec.l10n.format(policy.effectiveDate, 'yyyy-MM-dd')} to ${ec.l10n.format(policy.expirationDate, 'yyyy-MM-dd')}
Vehicle: ${policy.vehiclePlate ?: '-'} ${policy.vehicleDescription ?: ''}
Currency: ${policy.currencyUomId ?: 'the agency currency'}
Coverages:
${coverageText ?: '- none recorded'}
Notes from the agency: ${policy.description ?: '-'}"""
                if ('true'.equals(System.getenv('GROWERP_TEST_MODE'))) {
                    plainSummary = "• Test explanation of ${typeEnum?.description ?: 'the policy'}."
                } else {
                    def GeminiAiUtil = ec.resource.script("component://growerp/service/GeminiAiUtil.groovy", null)
                    plainSummary = GeminiAiUtil.callLlmApi(ec, prompt, [ownerPartyId: policy.ownerPartyId,
                        temperature: 0.3, maxOutputTokens: 1024, purpose: "insurance policy explanation"])?.trim()
                }

try {
    // own transaction: a failing search (no index, no embed key) must not
    // leave this one rollback-only for the LLM call below
    knowledge = ec.service.sync().name('AdkKnowledgeServices.search#AdkKnowledge')
        .parameters([ownerPartyId: ownerPartyId, query: question, limit: 4])
        .requireNewTransaction(true).call()?.results ?: []
} catch (Throwable t) {
    ec.logger.info("Insurance assistant: no knowledge search: ${t.message}")
}
ec.message.clearErrors()

import groovy.json.JsonOutput def facts = [ policies: own.policies.collect { [number: it.policyNumber ?: it.pseudoId, type: it.policyTypeEnumId, status: it.statusId, insurer: it.carrierName, plate: it.vehiclePlate, from: it.effectiveDate, until: it.expirationDate, renewalRequested: it.renewalRequestedDate, coverages: it.coverages] }, claims: ownClaims.claims.collect { [number: it.claimNumber ?: it.pseudoId, policy: it.policyNumber, status: it.statusId, incident: it.incidentDate, description: it.description, amountPaid: it.amountPaid, stillNeeded: it.missingEvidence] }] String kb = knowledge.collect { "[${it.title}] ${it.text}" }.join("\n---\n") String past = (history ?: []).takeRight(8).collect { "${it.role}: ${it.text}" }.join("\n") String prompt = """You are the assistant of an insurance agency, answering one of its clients in the app. Answer in the language of the client's question, in at most 5 short sentences. Rules: - Use only the client's data and the agency knowledge below. If the answer is not there, say you are not sure and that the agency will reply. - Never quote or estimate prices, never offer discounts or cashback, never create urgency. - Never say a claim will be approved, denied or how much will be paid: people decide that. - For a new claim point to "Report a claim" in the app; to renew, the "Request renewal" button on the policy card; proof of insurance is the QR code on the policy card. - If someone is hurt: tell them to call 115 (ambulance) and 113 (police) first. - Set "escalate" to true when the client asks for a person, complains, reports an emergency, or asks something you cannot answer from the data. Answer with JSON only: {"answer": "...", "escalate": true|false}
Client data (JSON, statuses are system codes: Inps* policy, Incl* claim): ${JsonOutput.toJson(facts)}
Agency knowledge: ${kb ?: 'none'}
Conversation so far: ${past ?: 'none'}
Client question: ${question}""" def reply if ('true'.equals(System.getenv('GROWERP_TEST_MODE'))) { reply = [answer: "Test answer: you have ${facts.policies.size()} policies.", escalate: false] } else { def GeminiAiUtil = ec.resource.script("component://growerp/service/GeminiAiUtil.groovy", null) String text = GeminiAiUtil.callLlmApi(ec, prompt, [ownerPartyId: ownerPartyId, jsonMode: true, temperature: 0.3, maxOutputTokens: 1024, purpose: "insurance client assistant"]) try { reply = GeminiAiUtil.parseJsonResponse(text) } catch (Throwable t) { reply = [answer: text, escalate: false] } } answer = reply.answer?.toString() escalated = reply.escalate == true

iterate.script:
byte[] imageBytes = Base64.getMimeDecoder().decode(photo.image.toString())
InputStream imageStream = new ByteArrayInputStream(imageBytes)
try { ec.resource.getLocationReference(contentLocation).putStream(imageStream) }
finally { imageStream.close() }

actions.script:
// runs async after the commit, in a worker without user: assess#Claim logs in
ec.service.special().name('growerp.100.InsuranceServices100.assess#Claim')
    .parameters([claimId: claimId, username: ec.user.username]).registerOnCommit()

service.description:
Background AI triage of a claim from its photos and description, advice
            for the adjuster; see service/insurance/assessClaim.groovy. A failure only logs:
            the claim stays Submitted and is handled as without AI.

actions.script:
try {
    ec.resource.script("component://growerp/service/insurance/assessClaim.groovy", null)
} catch (Throwable t) {
    ec.logger.warn("AI claim assessment of ${claimId} failed: ${t.message}")
    ec.message.clearErrors()
}
